import{_ as t,o,c as r,ah as a}from"./chunks/framework.Bja9t6Wf.js";const l=JSON.parse('{"title":"Judicial Aftermath: Thomas Schmid (The Archivist of Power)","description":"","frontmatter":{},"headers":[],"relativePath":"en/recherche/gericht-thomas-schmid.md","filePath":"en/recherche/gericht-thomas-schmid.md"}'),i={name:"en/recherche/gericht-thomas-schmid.md"};function h(s,e,n,c,m,d){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="judicial-aftermath-thomas-schmid-the-archivist-of-power" tabindex="-1">Judicial Aftermath: Thomas Schmid (The Archivist of Power) <a class="header-anchor" href="#judicial-aftermath-thomas-schmid-the-archivist-of-power" aria-label="Permalink to &quot;Judicial Aftermath: Thomas Schmid (The Archivist of Power)&quot;">​</a></h1><p><strong>From loyal confidant to the most important crown witness of the Second Republic.</strong></p><p>Thomas Schmid was the man at the center of the &quot;Kurz System.&quot; As Secretary General in the Ministry of Finance and later CEO of ÖBAG, he managed not only state assets but also the informal networks of power. His secured chats are the &quot;Rosetta Stones&quot; of modern Austrian corruption research.</p><hr><h2 id="significance-for-the-horten-mystery" tabindex="-1">Significance for &quot;The Horten Mystery&quot; <a class="header-anchor" href="#significance-for-the-horten-mystery" aria-label="Permalink to &quot;Significance for &quot;The Horten Mystery&quot;&quot;">​</a></h2><p>Thomas Schmid is the acoustic bridge in our project:</p><ul><li><strong>The Benko Axis:</strong> Schmid was René Benko&#39;s contact in the Ministry of Finance when it came to tax relief or COFAG aid.</li><li><strong>The Horten Donations:</strong> His chats provide the context for the &quot;aesthetic of splitting.&quot; He knew how to place donations to keep the system running without triggering an alarm.</li></ul><hr><p><em>Sources: Interrogation protocols of the WKStA, chat dossiers from ZackZack and Profil.</em></p>',9)])])}con